<script lang="ts">
  import { t as uiText } from './i18n.js';
  import {isImageAsset as isImage,isFontAsset as isFont} from './assets.js';
  interface Props {files?:Record<string,string>;onadd?:()=>void;onfont?:(path:string)=>void;onassign?:(path:string)=>void;oninsert?:(path:string)=>void;onfiles?:(files:File[])=>void}
  let {files={},onadd,onfont,onassign,oninsert,onfiles}:Props=$props();
  let search=$state(''),filter=$state('all'),folder=$state(''),selected=$state('');
  const paths=$derived(Object.keys(files).filter(p=>p.startsWith('assets/')&&!p.startsWith('assets/__studio_skins/')&&!p.startsWith('assets/__studio_fonts/')).sort());
  const folders=$derived([...new Set(paths.map(p=>p.slice(7,p.lastIndexOf('/'))).filter(Boolean))].sort());
  const shown=$derived(paths.filter(p=>(!search||p.toLocaleLowerCase().includes(search.toLocaleLowerCase()))&&(!folder||p.startsWith('assets/'+folder+'/'))&&(filter==='all'||filter==='image'&&isImage(p)||filter==='font'&&isFont(p))));
  function url(p:string){const ext=(p.split('.').pop()??'').toLowerCase();const mime=({png:'image/png',jpg:'image/jpeg',jpeg:'image/jpeg',svg:'image/svg+xml',webp:'image/webp',gif:'image/gif'} as Record<string,string>)[ext];return mime&&files[p]?`data:${mime};base64,${files[p]}`:'';}
  function picked(p:string){selected=p;}
</script>
<!-- svelte-ignore a11y_no_static_element_interactions -->
<div class="asset-browser" ondragover={(e)=>{if(e.dataTransfer?.types.includes('Files'))e.preventDefault();}} ondrop={(e)=>{if(e.dataTransfer?.files.length){e.preventDefault();onfiles?.([...e.dataTransfer?.files]);}}}>
  <div class="asset-actions"><button class="primary" onclick={onadd}>{$uiText("＋ Thêm asset")}</button><span>{paths.length} {$uiText("tài nguyên")}</span></div>
  <input aria-label={$uiText("Tìm asset")} placeholder={$uiText("Tìm ảnh, icon, font…")} bind:value={search} />
  <div class="asset-filters"><select aria-label={$uiText("Loại asset")} bind:value={filter}><option value="all">{$uiText("Tất cả")}</option><option value="image">{$uiText("Hình ảnh")}</option><option value="font">{$uiText("Font chữ")}</option></select><select aria-label={$uiText("Thư mục asset")} bind:value={folder}><option value="">{$uiText("Mọi thư mục")}</option>{#each folders as dir}<option value={dir}>{dir}</option>{/each}</select></div>
  <div class="asset-grid">{#each shown as p}<button class:selected={selected===p} class="asset-tile" title={$uiText("{0}\nKéo vào canvas; bấm đúp để thêm ảnh", p)} draggable={isImage(p)||isFont(p)} ondragstart={(e)=>e.dataTransfer?.setData('text/plain',(isFont(p)?'font:':'asset:')+p)} onclick={()=>picked(p)} ondblclick={()=>{if(isImage(p))oninsert?.(p);else if(isFont(p))onfont?.(p);}}>{#if isImage(p)}<span class="thumb"><img src={url(p)} alt={p.split('/').pop()} loading="lazy" decoding="async" /></span>{:else}<span class="font-icon">{isFont(p)?'Aa':'▤'}</span>{/if}<span class="asset-name">{p.split('/').pop()}</span></button>{/each}
    {#if !shown.length}<p class="asset-empty">{paths.length?$uiText("Không có asset khớp bộ lọc."):$uiText("Chưa có asset. Bấm “Thêm asset”, kéo tệp vào đây hoặc mở một mẫu.")}</p>{/if}
  </div>
  {#if selected&&files[selected]}<div class="asset-selection"><span title={selected}>{selected.slice(7)}</span>{#if isImage(selected)}<div><button onclick={()=>onassign?.(selected)}>{$uiText("Gán cho ảnh đang chọn")}</button><button onclick={()=>oninsert?.(selected)}>{$uiText("＋ Tạo ảnh")}</button></div>{:else}<button disabled={!isFont(selected)} onclick={()=>onfont?.(selected)}>{$uiText("Áp dụng font cho thành phần đang chọn")}</button>{/if}</div>{/if}
  <p class="asset-help">{$uiText("Tệp mới: ảnh → images/ · font → fonts/. Kéo ảnh vào canvas/Scene; bấm đúp font để áp dụng.")}</p>
</div>
<style>.asset-browser{display:flex;flex-direction:column;gap:7px;padding:8px;flex:1;min-height:0;overflow:hidden}.asset-actions{display:flex;justify-content:space-between;align-items:center;gap:6px}.asset-actions button{font-size:11px;padding:5px 8px}.asset-actions span{font-size:10px;color:#9bb0c9}.asset-browser>input{font-size:11px;padding:6px;flex-shrink:0}.asset-filters{display:flex;gap:5px}.asset-filters select{width:50%;font-size:10px;padding:5px}.asset-grid{overflow:auto;display:grid;grid-template-columns:repeat(auto-fill,minmax(76px,1fr));gap:6px;align-content:start;flex:1;min-height:60px}.asset-tile{display:flex;flex-direction:column;align-items:center;gap:5px;padding:5px;min-width:0;border:1px solid #43536a;background:#253246}.asset-tile.selected{border-color:#8cbef6;background:#3b5574}.thumb{height:54px;width:100%;display:flex;align-items:center;justify-content:center;background:repeating-conic-gradient(#445066 0% 25%,#303c50 0% 50%) 0/12px 12px;border-radius:3px}.thumb img{max-width:100%;max-height:100%;object-fit:contain;image-rendering:pixelated}.asset-name{width:100%;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font-size:9px}.font-icon{font-size:30px;color:#b8d7fa;height:54px}.asset-empty{grid-column:1/-1;font-size:11px;color:#9cafc7;line-height:1.6;margin:8px 0}.asset-selection{padding-top:6px;border-top:1px solid #465976}.asset-selection>span{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:#b4d5fa;font-size:10px;margin-bottom:5px}.asset-selection>div{display:flex;gap:5px}.asset-selection button{font-size:9px;padding:5px}.asset-help{font-size:9px;line-height:1.4;color:#8fa4bf;margin:0}</style>
